/**
 * Cassettes: recorded second-pass replies, one JSON file per request, keyed by
 * a stable hash of (adapter, model, request body). Tests and the eval replay
 * them so CI needs no network or keys (AGENTS.md rule 9). Pure: loading files
 * is the caller's job (scripts / tests / eval).
 */
import type { ContextPacket, Hypothesis, Rescorer } from '../types'
import type { AdapterId, RescoreCodec } from './codecs'
import { finishRescore } from './rescore'

export const CASSETTE_SCHEMA = 'brush.cassette/v1'
export const SYNTHETIC_NOTE =
  'SYNTHETIC: generated by a deterministic oracle-with-noise simulator that knows the label. Proves plumbing (parse, fusion, timing, rule 6), NOT model quality.'

export interface Cassette {
  schema: typeof CASSETTE_SCHEMA
  adapter: AdapterId
  model: string
  requestHash: string
  /** Human-readable summary: corpus file, first-pass candidates, room. Never used for lookup. */
  requestSummary: Record<string, unknown>
  /** The exact JSON body that was (or would be) sent. */
  request: Record<string, unknown>
  /** Raw JSON reply, in the adapter's own shape. */
  response: unknown
  latencyMs: number
  recordedAt: string
  synthetic: boolean
  note?: string
}

/** JSON with object keys sorted recursively; arrays keep order; undefined members dropped. */
export function canonicalJson(x: unknown): string {
  if (x === null || typeof x !== 'object') {
    if (typeof x === 'number' && !Number.isFinite(x)) return 'null'
    return JSON.stringify(x) ?? 'null'
  }
  if (Array.isArray(x)) return `[${x.map((v) => (v === undefined ? 'null' : canonicalJson(v))).join(',')}]`
  const o = x as Record<string, unknown>
  const keys = Object.keys(o)
    .filter((k) => o[k] !== undefined)
    .sort()
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalJson(o[k])}`).join(',')}}`
}

/** 64-bit (two 32-bit lanes, cyrb53-style mixing) hex hash of a string. Stable across platforms. */
export function hash64(s: string): string {
  let h1 = 0xdeadbeef ^ 0
  let h2 = 0x41c6ce57 ^ 0
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i)
    h1 = Math.imul(h1 ^ c, 2654435761)
    h2 = Math.imul(h2 ^ c, 1597334677)
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909)
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909)
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0')
}

/** The cassette key for a request. */
export function requestHash(adapter: AdapterId, model: string, body: unknown): string {
  return hash64(canonicalJson({ adapter, model, body }))
}

export function isCassette(x: unknown): x is Cassette {
  const c = x as Cassette
  return !!c && c.schema === CASSETTE_SCHEMA && typeof c.requestHash === 'string' && typeof c.adapter === 'string' && typeof c.latencyMs === 'number'
}

export class CassetteMissError extends Error {
  constructor(readonly hash: string, adapter: string) {
    super(`no cassette for ${adapter} request ${hash} (re-record, or regenerate the synthetic set: pnpm exec tsx scripts/record-cassettes.ts --synthetic)`)
    this.name = 'CassetteMissError'
  }
}

export class AbortedError extends Error {
  constructor() {
    super('second pass aborted')
    this.name = 'AbortError'
  }
}

export type Sleep = (ms: number, signal?: AbortSignal) => Promise<void>

/** setTimeout-based abortable sleep (timers are not network; allowed in core). */
export const realSleep: Sleep = (ms, signal) =>
  new Promise<void>((resolve, reject) => {
    if (signal?.aborted) return reject(new AbortedError())
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort)
      resolve()
    }, Math.max(0, ms))
    const onAbort = () => {
      clearTimeout(t)
      reject(new AbortedError())
    }
    signal?.addEventListener('abort', onAbort, { once: true })
  })

export interface CassetteRescorerOptions {
  codec: RescoreCodec
  cassettes: Iterable<Cassette>
  /** Fusion weight (RescoreSettings.weight). */
  weight: number
  /** Simulated latency: the recorded latencyMs times `latencyScale` (default 1), or a fixed `latencyMs`. */
  latencyMs?: number
  latencyScale?: number
  sleep?: Sleep
}

/** Replays recorded replies by request hash, with simulated latency. Implements the frozen Rescorer. */
export class CassetteRescorer implements Rescorer {
  readonly name: string
  readonly byHash = new Map<string, Cassette>()
  private readonly opts: CassetteRescorerOptions

  constructor(opts: CassetteRescorerOptions) {
    this.opts = opts
    this.name = `cassette:${opts.codec.adapter}`
    for (const c of opts.cassettes) if (c.adapter === opts.codec.adapter && c.model === opts.codec.model) this.byHash.set(c.requestHash, c)
  }

  /** The cassette this packet would replay, if any (no latency). */
  lookup(packet: ContextPacket): Cassette | undefined {
    const { codec } = this.opts
    return this.byHash.get(requestHash(codec.adapter, codec.model, codec.buildRequest(packet)))
  }

  async rescore(packet: ContextPacket, candidates: Hypothesis[], signal?: AbortSignal): Promise<Hypothesis[]> {
    const { codec } = this.opts
    const hash = requestHash(codec.adapter, codec.model, codec.buildRequest(packet))
    const c = this.byHash.get(hash)
    if (!c) throw new CassetteMissError(hash, codec.adapter)
    const ms = this.opts.latencyMs ?? c.latencyMs * (this.opts.latencyScale ?? 1)
    await (this.opts.sleep ?? realSleep)(ms, signal)
    return finishRescore(codec, c.response, packet, candidates, this.opts.weight)
  }
}
